// ── FUNCIÓN CENTRAL DE MATCH DE PROCEDIMIENTO ──────────────
// Separada como función para reutilizarla en handoff_received y selecting_procedure
const matchProcedure = (inputTxtN, procs) => {
  let matched = null;

  // Match 1: número
  const num = parseInt(inputTxtN);
  if (!isNaN(num) && num >= 1 && num <= procs.length) matched = procs[num - 1];

  // Match 2: nombre completo o key (normalizado, bidireccional)
  if (!matched) matched = procs.find(p =>
    inputTxtN.includes(normalize(p.name))   ||
    inputTxtN.includes(normalize(p.nameEn)) ||
    inputTxtN.includes(normalize(p.namePt)) ||
    inputTxtN.includes(p.key.replace(/_/g, ' '))
  );

  // Match 3: palabras significativas del nombre español (>4 chars)
  if (!matched) matched = procs.find(p => {
    const words = normalize(p.name).split(' ').filter(w => w.length > 4);
    return words.some(w => inputTxtN.includes(w));
  });

  // Match 4: aliases (bidireccional: alias IN txt OR txt-word IN alias)
  if (!matched) matched = procs.find(p => {
    const aliases = PROCEDURE_ALIASES[p.key] || [];
    return aliases.some(a => {
      const aN = normalize(a);
      // Alias corto dentro del texto del usuario: 'rinplas' in 'rinplastia' ✓
      if (aN.length >= 4 && inputTxtN.includes(aN)) return true;
      // Texto del usuario dentro del alias: 'rhinoplasty' in 'rhinoplasty (nose job)' ✓
      if (inputTxtN.length >= 5) {
        const userWords = inputTxtN.split(/[\s,]+/).filter(w => w.length >= 4);
        return userWords.some(w => aN.includes(w));
      }
      return false;
    });
  });

  // Match 5: prefix mínimo de 5 chars del nombre clave
  // Captura casos como 'blefarop' → 'blefaroplastia'
  if (!matched) matched = procs.find(p => {
    const keyN = normalize(p.key.replace(/_/g, ''));
    const userWords = inputTxtN.split(/[\s,]+/).filter(w => w.length >= 5);
    return userWords.some(w => keyN.startsWith(w.substring(0, 7)) || keyN.includes(w.substring(0, 6)));
  });

  return matched;
};

