  const kPlastic = /plastic|cirugia|rinoplas|rinplas|liposu|abdominoplas|mamario|busto|seno|bichec|blefaroplas|blefaro|otoplas|lifting|bbl|nariz|glut|rhinoplasty|liposuction|tummy tuck|breast|facelift|face lift|blepharoplasty|ear surgery|nose job|butt lift|augmentation|mamoplastia|lipoaspiracao|seios|arrug|flacid|rejuven|papada|mejill|parpad|orej|aesthetic|estetica|apariencia/i;
  const isDental  = kDental.test(inputTxtN)  || inputTxtN === '1';
  const isPlastic = kPlastic.test(inputTxtN) || inputTxtN === '2';
  if (isDental && !isPlastic) return 'dental';
  if (isPlastic) return 'plastic_surgery';
  if (isDental) return 'dental'; // tie → dental
  return null;
};

