let intakePayload    = null;

switch(state) {

  // ── BIENVENIDA ─────────────────────────────────────────────
  case 'welcome': {
    // FIX v2.2.2: verificar perfil antes de comenzar cotización
    if (!patProfileOk) {
      sage.state = 'gathering_profile';
      sage.profile_step = 1;
      rt = LANG === 'en'
        ? `Hello${nm}, I'm *SAGE* 🩺 your medical quotes specialist at Pangi.\n\nBefore we start, I need a few quick details to personalize your request.\n\n*How old are you?*`
        : LANG === 'pt'
        ? `Olá${nm}, sou *SAGE* 🩺 sua especialista em cotações médicas da Pangi.\n\nAntes de começar, preciso de alguns dados rápidos.\n\n*Quantos anos você tem?*`
        : `Hola${nm}, soy *SAGE* 🩺 tu especialista en cotizaciones de Pangi.\n\nAntes de empezar, necesito unos datos rápidos para personalizar tu solicitud.\n\n*¿Cuántos años tienes?*`;
      break;
    }
    rt = t('welcome', {nm});
    sage.state = 'selecting_specialty';
    break;
  }

  // ── HANDOFF RECIBIDO ────────────────────────────────────────
  // v2.0.8 FIX: Usa txt (mensaje actual) PRIMERO. Solo usa pendingMessage
  // como fallback si txt no tiene información de especialidad/procedimiento.
  // v2.2.3 FIX: NO verificar perfil aquí — esta case puede correr en el
  // mismo ciclo que NOVA (causando active_agent='NOVA' en la DB).
  // El perfil se verifica en procedure_confirmed, que siempre corre
  // cuando la sesión ya tiene active_agent='SAGE' correctamente.
  case 'handoff_received': {
    const rawPending  = sage.pendingMessage || '';
    sage.pendingMessage = null; // siempre consumir

    // Si el mensaje actual es afirmación genérica o número solo,
    // no usarlo para detección — el contexto real está en pendingMessage
    const isGenericInput = /^(1|2|s[íi]|si|yes|ok|dale|listo|ready|pronto|sure|claro|adelante|sim|\d)$/i.test(txt.trim());
    const txtNH   = isGenericInput ? '' : txtN;
    const pendTxtN = normalize(rawPending);

    // Determinar qué texto procesar: txt actual tiene prioridad
    const spTxt  = detectSpecialty(txtNH);
    const spPend = detectSpecialty(pendTxtN);
    const workingTxtN = spTxt ? txtNH : (spPend ? pendTxtN : txtNH);
    const workingSp   = spTxt || spPend;

    if (workingSp) {
      const procsH = PROCEDURES[workingSp];
      sage.specialty = workingSp;
      const matchedH = matchProcedure(workingTxtN, procsH) ||
                       (workingTxtN !== pendTxtN ? matchProcedure(pendTxtN, procsH) : null);

      if (matchedH) {
        sage.procedure_key  = matchedH.key;
        sage.procedure_name = procName(matchedH);
        sage.state = 'procedure_confirmed';
        rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_ready', {nm, procedure: procName(matchedH)});
        break;
      }

      // Especialidad detectada pero sin procedimiento → lista directa
      const emojiH = workingSp === 'dental' ? '🦷' : '💉';
      const listH  = procsH.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
      sage.state = 'selecting_procedure';
      rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_prompt', {nm, emoji: emojiH, list: listH});
      break;
    }

    // Sin especialidad → bienvenida normal
    sage.state = 'selecting_specialty';
    rt = t('welcome', {nm});
    break;
  }

  // ── SELECCIÓN DE ESPECIALIDAD ──────────────────────────────
  case 'selecting_specialty': {
    const sp = detectSpecialty(txtN);
    if (!sp) {
      rt = t('specialty_error', {nm});
      break;
    }
    sage.specialty = sp;
    // FIX v2.2.2: intentar match de procedimiento inmediatamente.
    // Si el usuario ya mencionó el procedimiento ("rinoplastía", "implante"),
    // saltar la lista y confirmar directamente → evita el paso extra frustrante.
    const procsForSp  = PROCEDURES[sp];
    const directMatch = matchProcedure(txtN, procsForSp);
    if (directMatch) {
      sage.procedure_key  = directMatch.key;
      sage.procedure_name = procName(directMatch);
      sage.state          = 'procedure_confirmed';
      rt = t('procedure_ready', {nm, procedure: procName(directMatch)});
      break;
    }
    // Sin procedimiento específico → mostrar lista
    const emoji = sp === 'dental' ? '🦷' : '💉';
    const list  = procsForSp.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
    rt = t('procedure_prompt', {nm, emoji, list});
    sage.state = 'selecting_procedure';
    break;
  }

  // ── SELECCIÓN DE PROCEDIMIENTO ─────────────────────────────
  case 'selecting_procedure': {
    const sp    = sage.specialty || 'dental';
    const procs = PROCEDURES[sp] || [];
    const matched = matchProcedure(txtN, procs);

    // Cross-specialty: si no hay match en especialidad actual → probar la otra
    if (!matched) {
      const otherSp    = sp === 'dental' ? 'plastic_surgery' : 'dental';
      const crossMatch = matchProcedure(txtN, PROCEDURES[otherSp]);
      if (crossMatch) {
        sage.specialty      = otherSp;
        sage.procedure_key  = crossMatch.key;
        sage.procedure_name = procName(crossMatch);
        sage.state          = 'procedure_confirmed';
        rt = t('procedure_ready', {nm, procedure: procName(crossMatch)});
        break;
      }
      const emoji = sp === 'dental' ? '🦷' : '💉';
      const list  = procs.map((p, i) => `${i + 1}. ${procName(p)}`).join('\n');
      rt = t('procedure_error', {nm, emoji, list});
      break;
    }

    sage.procedure_key  = matched.key;
    sage.procedure_name = procName(matched);
    sage.state          = 'procedure_confirmed';
    rt = t('procedure_ready', {nm, procedure: procName(matched)});
    break;
  }

  // ── PROCEDIMIENTO CONFIRMADO ────────────────────────────────
  case 'procedure_confirmed': {
    // v2.2.3 FIX: Verificar perfil aquí — este case siempre corre con
    // active_agent='SAGE' ya correctamente guardado en la DB.
    // Nunca corre en el mismo ciclo que NOVA.
    if (!patProfileOk) {
      // Guardar procedimiento como pendiente para retomar después del perfil
      sage._prof_sp         = sage.specialty        || null;
      sage._prof_proc_key   = sage.procedure_key    || null;
      sage._prof_proc_name  = sage.procedure_name   || null;
      sage.state      = 'gathering_profile';
      sage.profile_step = 1;
      rt = LANG === 'en'
        ? `Before we start your *${sage._prof_proc_name || 'procedure'}* quote, I need a few quick details about you.\n\n*How old are you?*`
        : LANG === 'pt'
        ? `Antes de começar sua cotação de *${sage._prof_proc_name || 'procedimento'}*, preciso de alguns dados sobre você.\n\n*Quantos anos você tem?*`
        : `Antes de empezar tu cotización de *${sage._prof_proc_name || 'procedimiento'}*, necesito unos datos rápidos sobre ti.\n\n*¿Cuántos años tienes?*`;
      break;
    }
    if (!procData) { rt = t('kb_loading', {nm}); break; }

    const rawQ = parseArr(procData.critical_questions);
    const isObjFmt = rawQ.length > 0 && typeof rawQ[0] === 'object';
    let questions, infoKeys;
    if (isObjFmt) {
      questions = rawQ.map(q => q.question);
      infoKeys  = rawQ.map(q => q.key);
    } else {
      questions = rawQ;
      infoKeys  = parseArr(procData.required_info);
    }

    sage.critical_questions = questions;
    sage.required_info      = infoKeys;
    sage.required_exams     = parseArr(procData.required_exams);
    sage.typical_recovery   = procData.typical_recovery_days || 3;
    sage.collected_data     = {};
    sage.current_q_index    = 1;
    sage.state              = 'questioning';

    const intro = LANG === 'en'
      ? `Let's prepare your *${sage.procedure_name}* quote:`
      : LANG === 'pt'
      ? `Vamos preparar sua cotação de *${sage.procedure_name}*:`
      : (procData.sage_intro_message || `Empecemos con *${sage.procedure_name}*:`);

    const q1Header = LANG === 'en'
      ? `*Question 1 of ${questions.length}:*`
      : LANG === 'pt'
      ? `*Pergunta 1 de ${questions.length}:*`
      : `*Pregunta 1 de ${questions.length}:*`;

    rt = `${intro}\n\n${q1Header}\n${questions[0]}`;

    shouldSaveIntake = true;
    intakePayload = { operation: 'saveMedicalIntake', params: {
      userId: inp.userId, sessionId: inp.sessionId, specialty: sage.specialty,
      procedureName: sage.procedure_name, collectedData: {}, missingItems: sage.required_exams, score: 0
    }};
    break;
  }

  // ── Q&A ────────────────────────────────────────────────────
  case 'questioning': {
    // ESCAPE: usuario quiere salir explícitamente hacia ATLAS
    if (isEscapeToAtlas) {
      const score = sage.completeness_score || 0;
      rt  = t('escape_offer', {nm, procedure: sage.procedure_name || '—', score});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id,
        collectedData: sage.collected_data || {},
        missingItems: sage.required_exams || [],
        score,
        status: 'in_progress'
      }};
      break;
    }

    const questions  = sage.critical_questions || [];
    const infoKeys   = sage.required_info      || [];
    const currentIdx = sage.current_q_index    || 1;
    const collected  = { ...(sage.collected_data || {}) };
    const totalQ     = questions.length;

    if (infoKeys[currentIdx - 1]) collected[infoKeys[currentIdx - 1]] = inp.messageText;
    sage.collected_data = collected;

    const answeredCount = Object.keys(collected).length;
    const baseScore = Math.round((answeredCount / totalQ) * 85);
    const examBonus = (sage.required_exams || []).some(e =>
      txtN.includes(normalize(e).substring(0, 5))
    ) ? 15 : 0;
    const score = Math.min(100, baseScore + examBonus);
    sage.completeness_score = score;
    const scoreLabel = score >= 80 ? t('score_excellent') : score >= 60 ? t('score_good') : t('score_basic');

    if (currentIdx >= totalQ) {
      sage.current_q_index = currentIdx;
      sage.state = 'summary';

      const summaryLines = Object.entries(collected)
        .map(([k, v]) => `✅ *${k.replace(/_/g,' ').replace(/^\w/, c => c.toUpperCase())}:* ${v}`)
        .join('\n');

      const examsArr  = sage.required_exams || [];
      const examsList = examsArr.length > 0
        ? t('exams_header', {items: examsArr.map(e => `• ${e.replace(/_/g,' ')}`).join('\n')})
        : '';

      rt = t('summary_header', {nm, procedure: sage.procedure_name, lines: summaryLines, exams: examsList, score, label: scoreLabel});

      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: collected,
        missingItems: sage.required_exams, score, status: 'in_progress'
      }};
    } else {
      sage.current_q_index = currentIdx + 1;
      rt = `*${questions[currentIdx]}*\n\n${t('question_progress', {n: currentIdx + 1, total: totalQ, score})}`;

      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: collected,
        missingItems: sage.required_exams, score
      }};
    }
    break;
  }

  // ── RESUMEN ─────────────────────────────────────────────────
  case 'summary': {
    const isConfirm = /confirm|si|yes|enviar|publicar|listo|ok|dale|adelante/i.test(txt);
    if (isConfirm) {
      rt = t('published', {nm, name_comma: fn ? ', ' + fn : '', procedure: sage.procedure_name});
      sage.state = 'complete';
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, status: 'submitted', score: sage.completeness_score || 0
      }};
    } else {
      const prev = sage.collected_data || {};
      prev['detalle_adicional'] = inp.messageText;
      sage.collected_data = prev;
      const newScore = Math.min(100, (sage.completeness_score || 70) + 8);
      sage.completeness_score = newScore;
      rt = t('added_details', {nm, score: newScore});
      shouldSaveIntake = true;
      intakePayload = { operation: 'updateMedicalIntake', params: {
        intakeId: sage.intake_id, collectedData: prev, score: newScore
      }};
    }
    break;
  }

  // ── COMPLETO ────────────────────────────────────────────────
  case 'complete':
  case 'waiting_for_quotes': {
    const wantsAtlas = /atlas|compar|destino|si|sí|yes|quiero|dale|adelante|compare|destination|sure|go ahead|connect me|sim|quero|destinos|vamos/i.test(txt);
    const allProcs   = [...PROCEDURES.dental, ...PROCEDURES.plastic_surgery];
    const newProcMatch = !wantsAtlas ? matchProcedure(txtN, allProcs) : null;

    if (wantsAtlas) {
      rt  = t('connecting_atlas', {nm, procedure: sage.procedure_name});
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
    } else if (newProcMatch && newProcMatch.key !== sage.procedure_key) {
      const newSp = PROCEDURES.dental.find(p => p.key === newProcMatch.key) ? 'dental' : 'plastic_surgery';
      sage.specialty           = newSp;
      sage.procedure_key       = newProcMatch.key;
      sage.procedure_name      = newProcMatch.name;
      sage.state               = 'procedure_confirmed';
      sage.collected_data      = {};
      sage.current_q_index     = 1;
      sage.completeness_score  = 0;
      sage.intake_id           = null;
      rt = t('intro_brief', {nm}) + '\n\n' + t('procedure_ready', {nm, procedure: procName(newProcMatch)});
    } else {
      rt = t('wait_quotes', {nm});
      sage.state = 'waiting_for_quotes';
    }
    break;
  }

  // ── RECOPILACIÓN DE PERFIL BÁSICO DEL PACIENTE ────────────
  // Estado transitorio antes de comenzar el Q&A de cotización.
  // 3 preguntas: edad → sexo biológico → condiciones médicas.
  // En producción: se salta si MongoDB ya tiene estos datos.
  case 'gathering_profile': {
    const pStep   = sage.profile_step || 1;
    const profile = { ...(ctx.patientProfile || {}) };

    if (pStep === 1) {
      // Esperando edad
      const ageStr = (txt.match(/\d+/) || [])[0];
      const age    = ageStr ? parseInt(ageStr) : NaN;
      if (!ageStr || isNaN(age) || age < 12 || age > 100) {
        rt = LANG === 'en'
          ? `I need your age to continue${nm}. Please write a number between 12 and 100.`
          : LANG === 'pt'
          ? `Preciso da sua idade para continuar${nm}. Por favor escreva um número entre 12 e 100.`
          : `Necesito tu edad para continuar${nm}. Por favor escribe solo el número (ej: 35).`;
        break;
      }
      profile.age       = age;
      ctx.patientProfile = profile;
      sage.profile_step  = 2;
      rt = LANG === 'en'
        ? `${age} years old ✅\n\n*What is your biological sex?*\n1️⃣ Male\n2️⃣ Female`
        : LANG === 'pt'
        ? `${age} anos ✅\n\n*Qual é o seu sexo biológico?*\n1️⃣ Masculino\n2️⃣ Feminino`
        : `${age} años ✅\n\n*¿Cuál es tu sexo biológico?*\n1️⃣ Masculino\n2️⃣ Femenino`;
      break;
    }

    if (pStep === 2) {
      // Esperando sexo biológico
      const isMale   = /\b(male|man|masculin|hombre|masculino|homem)\b|^(1|m)$/i.test(txt.trim());
      const isFemale = /\b(female|woman|femenin|mujer|femenino|mulher)\b|^(2|f)$/i.test(txt.trim());
      if (!isMale && !isFemale) {
        rt = LANG === 'en'
          ? `I didn't catch that. You can write *Male*, *Female*, *1* or *2*.`
          : LANG === 'pt'
          ? `Não entendi. Você pode escrever *Masculino*, *Feminino*, *1* ou *2*.`
          : `No entendí bien. Puedes escribir *Masculino*, *Femenino*, *1* o *2*.`;
        break;
      }
      profile.sex        = isMale ? 'M' : 'F';
      ctx.patientProfile = profile;
      sage.profile_step  = 3;
      const sexLabel = isMale
        ? (LANG === 'en' ? 'Male' : LANG === 'pt' ? 'Masculino' : 'Masculino')
        : (LANG === 'en' ? 'Female' : LANG === 'pt' ? 'Feminino' : 'Femenino');
      rt = LANG === 'en'
        ? `${sexLabel} ✅\n\n*Do you have any known medical conditions?*\nExamples: diabetes, hypertension, heart disease, medication allergies.`
        : LANG === 'pt'
        ? `${sexLabel} ✅\n\n*Você tem alguma condição médica conhecida?*\nExemplos: diabetes, hipertensão, doenças cardíacas, alergias a medicamentos.`
        : `${sexLabel} ✅\n\n*¿Tienes alguna condición médica conocida?*\nEj: diabetes, hipertensión, enf. cardíacas, alergias a medicamentos.`;
      break;
    }

    if (pStep === 3) {
      // Cualquier respuesta es válida para condiciones médicas
      const noConds = /^(no$|ninguna|none|nenhuma|nao$|não$|no tengo|n\/a$|nothing|no conditions|i don't have|i have none|no tengo nada|sin enfermedades|ninguna condición|não tenho|nada$)/i.test(txt.trim());
      profile.conditions = noConds
        ? (LANG === 'en' ? 'None' : LANG === 'pt' ? 'Nenhuma' : 'Ninguna')
        : inp.messageText;
      ctx.patientProfile = profile;
      sage.profile_step  = 'done';

      // Resumen del perfil
      const sexDisplay = profile.sex === 'M'
        ? (LANG === 'en' ? 'Male' : 'Masculino')
        : (LANG === 'en' ? 'Female' : 'Femenino');
      const profSummary = LANG === 'en'
        ? `✅ *Profile:* ${profile.age}y · ${sexDisplay} · ${profile.conditions}`
        : LANG === 'pt'
        ? `✅ *Perfil:* ${profile.age}a · ${sexDisplay} · ${profile.conditions}`
        : `✅ *Perfil:* ${profile.age} años · ${sexDisplay} · ${profile.conditions}`;

      // Recuperar contexto pendiente (guardado en handoff_received)
      const pendSp       = sage._prof_sp        || null;
      const pendProcKey  = sage._prof_proc_key  || null;
      const pendProcName = sage._prof_proc_name || null;
      delete sage._prof_sp; delete sage._prof_proc_key; delete sage._prof_proc_name;

      if (pendProcKey) {
        // Había procedimiento detectado → saltar directo a procedure_confirmed
        sage.specialty      = pendSp;
        sage.procedure_key  = pendProcKey;
        sage.procedure_name = pendProcName;
        sage.state          = 'procedure_confirmed';
        rt = profSummary + '\n\n' + t('procedure_ready', {nm, procedure: pendProcName});
      } else if (pendSp) {
        // Había especialidad → mostrar lista de procedimientos
        sage.specialty = pendSp;
        sage.state     = 'selecting_procedure';
        const emoji    = pendSp === 'dental' ? '🦷' : '💉';
        const list     = PROCEDURES[pendSp].map((p,i) => `${i+1}. ${procName(p)}`).join('\n');
        rt = profSummary + '\n\n' + t('procedure_prompt', {nm, emoji, list});
      } else {
        // Sin contexto previo → mostrar selección de especialidad
        sage.state = 'selecting_specialty';
        rt = profSummary + '\n\n' + (LANG === 'en'
          ? `Now, *which specialty do you need a quote for?*\n\n🦷 Type *1* or *dental*\n💉 Type *2* or *plastic surgery*`
          : LANG === 'pt'
          ? `Agora, *para qual especialidade você precisa de cotação?*\n\n🦷 Escreva *1* ou *dental*\n💉 Escreva *2* ou *cirurgia plástica*`
          : `Ahora, *¿para qué especialidad necesitas cotizar?*\n\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`);
      }
      break;
    }

    // Fallback step inválido
    rt = t('fallback', {nm});
    sage.state = 'welcome';
    break;
  }

  default: {
    rt = t('fallback', {nm});
    sage.state = 'welcome';
  }
}

return [{ json: {
  success:          true,
  responseText:     rt,
  newActiveAgent:   nag,
  newSessionState:  nss,
  newSageContext:   sage,
  inputContext:     ctx,
  shouldSaveIntake,
  intakePayload:    intakePayload || null,
  userId:           parseInt(inp.userId),
  sessionId:        parseInt(inp.sessionId),
  userLanguage:     inp.userLanguage || 'es',
  detectedLanguage: LANG,
  userName:         inp.userName || null,
  remoteJid:        inp.remoteJid,
  messageText:      inp.messageText || '',
  instance:         inp.instance
}}];

// messageText passthrough added

// Prepara el payload para save o update del intake médico.
// Si shouldSaveIntake=false, devuelve __skip__ para saltar la DB call.
const motor = $input.first().json;

if (!motor.shouldSaveIntake || !motor.intakePayload) {
  // No hay intake que guardar en este mensaje
  return [{ json: { operation: '__skip__', params: {}, _motorOutput: motor } }];
}

// Si el intake ya existe (intake_id en contexto), aseguramos que el payload sea update
const sage = motor.newSageContext || {};
if (motor.intakePayload.operation === 'updateMedicalIntake' && !sage.intake_id) {
  // Todavía no tenemos el intake_id (raro edge case) — skip
  return [{ json: { operation: '__skip__', params: {}, _motorOutput: motor } }];
}

return [{ json: { ...motor.intakePayload, _motorOutput: motor } }];

// ============================================================
// Construye la respuesta final de SAGE.
// FIX v2.2.0: persiste language en newSessionContext (issue #3)
// ============================================================

const dbResult    = $input.first().json;
const prepNode    = $('📦 Preparar — Guardar Intake').first().json;
const motorOutput = prepNode._motorOutput || dbResult._motorOutput;

if (!motorOutput) {
  return [{ json: {
    success: false,
    error:   'MOTOR_OUTPUT_LOST',
    responseText: 'Error interno. Por favor escribe de nuevo.',
    newActiveAgent: 'SAGE'
  }}];
}

// Actualizar intake_id si el intake fue recién creado
const sageCtx = { ...motorOutput.newSageContext };
const wasNewIntake = motorOutput.intakePayload && motorOutput.intakePayload.operation === 'saveMedicalIntake';
if (wasNewIntake && dbResult.success && dbResult.data && dbResult.data[0]) {
  sageCtx.intake_id = dbResult.data[0].id;
}

// Determinar idioma a persistir: usar el detectado/activo en esta interacción
const activeLang = motorOutput.detectedLanguage || motorOutput.userLanguage || 'es';

// Construir newSessionContext preservando otros agentes + language a nivel raíz
const newSessionContext = {
  ...(motorOutput.inputContext || {}),
  sage: sageCtx,
  language: activeLang   // FIX #3: idioma persistente para toda la sesión
};

return [{ json: {
  success:            true,
  responseText:       motorOutput.responseText,
  newActiveAgent:     motorOutput.newActiveAgent  || 'SAGE',
  newSessionState:    motorOutput.newSessionState || 'sage_active',
  newSessionContext,
  userId:             motorOutput.userId,
  sessionId:          motorOutput.sessionId,
  userLanguage:       motorOutput.userLanguage    || 'es',
  userName:           motorOutput.userName        || null,
  remoteJid:          motorOutput.remoteJid,
  instance:           motorOutput.instance
}}];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'SAGE_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
