  : LANG === 'en'
  ? 'Always respond in English.'
  : 'Responda SEMPRE em português.';

// ── Build prompt per state ────────────────────────────────────
let systemPrompt = '';
let userContent  = '';
let maxTokens    = 400;

// ─── STATE: questioning ───────────────────────────────────────
if (state === 'questioning') {
  const questions   = sage.critical_questions || [];
  const infoKeys    = sage.required_info      || [];
  const currentIdx  = (sage.current_q_index || 1);       // 1-based, NEXT question (motor already incremented)
  const prevIdx     = currentIdx - 1;                    // the question that WAS asked
  const totalQ      = questions.length;
  const collected   = sage.collected_data || {};
  const procedure   = sage.procedure_name || '';

  const qHeader = LANG === 'en'
  ? `*Question ${currentIdx} of ${totalQ}:*`
  : LANG === 'pt'
  ? `*Pergunta ${currentIdx} de ${totalQ}:*`
  : `*Pregunta ${currentIdx} de ${totalQ}:*`;

  // FIX v2.2.2: prevIdx===0 → mensaje de inicio (listo/ok/ready), NO respuesta a Q.
  // El motor en procedure_confirmed ya generó Q1 en responseText.
  // Saltar NLG evita que Claude evalúe "listo" como respuesta a pregunta vacía.
  if (prevIdx === 0) {
    if (LANG === 'es') {
      return [{ json: { ...raw, _nlgSkip: true, _nlgReason: 'start_signal_not_answer_es' } }];
