  }
  const langName = LANG === 'en' ? 'English' : 'Portuguese';
  const templateText = motor.responseText || '';

  systemPrompt = `You are SAGE, a medical quotes specialist at Pangi.
Always respond in ${langName}.

Translate the following message to ${langName}. It may be partially in Spanish — translate the Spanish parts and keep what is already in ${langName}:
---
${templateText}
---
Keep WhatsApp format (*bold*, emojis). Return ONLY the translated message, no explanations.`;

