// ============================================================
// PROCESAR NLG SAGE v2.2.0 — Paso 3
// FIX v2.2.0:
//   #1 — Coherencia Q&A: cuando isCoherent=false && !escapeIntent,
//        revierte el avance del motor (borra dato guardado + rollback
//        current_q_index) para re-hacer la misma pregunta.
//   #2 — Cambio de procedimiento: se maneja en el system prompt
//        (instrucción explícita de responseText para change_procedure)
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — NLG SAGE').first().json;

// Si fue skip → pasar sin cambios
if (prepData._nlgSkip) {
  return [{ json: { ...prepData, _nlgSource: 'motor_skip' } }];
}

const nlgState   = prepData._nlgState;
const motorOut   = prepData;
let   finalOut   = { ...motorOut };
finalOut._nlgSource = 'motor_fallback';

try {
  const rawText = httpResult?.content?.[0]?.text?.trim();
  if (!rawText || rawText.length < 5) throw new Error('empty_response');

  // ── STATE: questioning ──────────────────────────────────────
  if (nlgState === 'questioning') {
    const clean = rawText.replace(/```json\n?|```\n?/g, '').trim();
    const parsed = JSON.parse(clean);

    // ── FIX #1: incoherente SIN escape → revertir avance del motor ──────
    // El motor ya guardó la respuesta y avanzó current_q_index.
    // Deshacemos eso para re-preguntar la misma pregunta.
    if (parsed.isCoherent === false && !parsed.escapeIntent) {
      const sage     = { ...(finalOut.newSageContext || {}) };
      const infoKeys = sage.required_info      || [];
      const questions = sage.critical_questions || [];
      const totalQ   = questions.length;
      const collected = { ...(sage.collected_data || {}) };

      if (sage.state === 'summary') {
        // El motor puso state='summary' porque era la última pregunta.
        // current_q_index = totalQ (NO fue incrementado por el motor en este caso).
        // La key que se guardó mal es infoKeys[totalQ - 1].
        const keyToRemove = infoKeys[totalQ - 1];
        if (keyToRemove && keyToRemove in collected) {
          delete collected[keyToRemove];
        }
        sage.state = 'questioning'; // revertir a questioning para re-preguntar
        // current_q_index se queda en totalQ (correcto, seguimos en la última)
      } else {
        // El motor incrementó current_q_index: era N, ahora es N+1.
        // La key guardada erróneamente es infoKeys[N-1] = infoKeys[current_q_index - 2].
        const keyToRemove = infoKeys[(sage.current_q_index || 1) - 2];
        if (keyToRemove && keyToRemove in collected) {
          delete collected[keyToRemove];
        }
        sage.current_q_index = (sage.current_q_index || 2) - 1; // revertir N+1 → N
      }

      // Recalcular score con los datos corregidos
      const answeredCount = Object.keys(collected).length;
      sage.collected_data = collected;
      sage.completeness_score = Math.round((answeredCount / Math.max(totalQ, 1)) * 85);

      finalOut.newSageContext   = sage;
      finalOut.shouldSaveIntake = false; // no guardar dato incoherente
      finalOut.intakePayload    = null;

      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
      return [{ json: finalOut }]; // early return — no seguir procesando
    }

    // ── FIX: change_procedure — usuario quiere cambiar de procedimiento mid-Q&A ──
    if (parsed.isCoherent === false && parsed.escapeIntent === 'change_procedure' && parsed.newProcedureKey) {
      const sage      = { ...(finalOut.newSageContext || {}) };
      const DENTAL_KEYS = [
        'extraccion_simple','extraccion_muela_juicio','implante_dental','protesis_completa',
        'carillas_veneers','ortodoncia_brackets','ortodoncia_invisible','endodoncia',
        'corona_dental','limpieza_profunda','blanqueamiento','puente_dental'
      ];
      const newSp = DENTAL_KEYS.includes(parsed.newProcedureKey) ? 'dental' : 'plastic_surgery';

      // Reset completo del estado de cotización — el motor cargará el KB en el próximo mensaje
      sage.specialty          = newSp;
      sage.procedure_key      = parsed.newProcedureKey;
      sage.procedure_name     = parsed.newProcedureKey.replace(/_/g, ' '); // nombre provisional
      sage.state              = 'procedure_confirmed';
      sage.collected_data     = {};
      sage.current_q_index    = 1;
      sage.completeness_score = 0;
      sage.intake_id          = null;
      sage.critical_questions = null; // se recarga del KB en el próximo mensaje
      sage.required_info      = null;

      finalOut.newSageContext   = sage;
      finalOut.shouldSaveIntake = false;
      finalOut.intakePayload    = null;

      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
      return [{ json: finalOut }];
    }

    // ── FIX: abort — usuario quiere cancelar el formulario completamente ──────────
    if (parsed.isCoherent === false && parsed.escapeIntent === 'abort') {
      const sage = { ...(finalOut.newSageContext || {}) };
      sage.state              = 'selecting_specialty';
      sage.collected_data     = {};
      sage.current_q_index    = 1;
      sage.completeness_score = 0;
      sage.intake_id          = null;

      finalOut.newSageContext   = sage;
      finalOut.shouldSaveIntake = false;
      finalOut.intakePayload    = null;

      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
      return [{ json: finalOut }];
    }
    // ── Respuesta coherente: aplicar cleanAnswer y extraData ─────────
    if (parsed.isCoherent !== false) {
      const sage     = { ...(finalOut.newSageContext || {}) };
      const infoKeys = sage.required_info || [];
      // current_q_index ya fue incrementado por el motor; la pregunta anterior
      // que se acaba de responder es current_q_index - 1 (o totalQ para summary).
      const isSummaryState = sage.state === 'summary';
      const totalQ         = (sage.critical_questions || []).length;
      const prevIdx        = isSummaryState
        ? totalQ                                   // última pregunta: index = totalQ
        : (sage.current_q_index || 1) - 1;         // no última: index = N (antes del increment)
      const prevKey = infoKeys[prevIdx - 1];        // 0-indexed

      if (prevKey && parsed.cleanAnswer) {
        const collected = { ...(sage.collected_data || {}) };
        collected[prevKey] = parsed.cleanAnswer;

