        // FIX #2: limpiar COMPLETAMENTE el estado anterior antes de cambiar
        const dentalKeys = ['extraccion_simple','extraccion_muela_juicio','implante_dental',
          'protesis_completa','carillas_veneers','ortodoncia_brackets','ortodoncia_invisible',
          'endodoncia','corona_dental','limpieza_profunda','blanqueamiento','puente_dental'];
        const allProcNames = {
          rinoplastia:'Rinoplastia', abdominoplastia:'Abdominoplastia',
          liposuccion:'Liposucción', aumento_mamario:'Aumento de Busto',
          reduccion_mamaria:'Reducción de Busto', bichectomia:'Bichectomía',
          blefaroplastia:'Blefaroplastia (Párpados)', otoplastia:'Otoplastia (Orejas)',
          lifting_facial:'Lifting Facial', bbl:'BBL (Brazilian Butt Lift)',
          extraccion_simple:'Extracción Simple',
          extraccion_muela_juicio:'Extracción Muela del Juicio',
          implante_dental:'Implante Dental', protesis_completa:'Prótesis Dental Completa',
          carillas_veneers:'Carillas / Veneers', ortodoncia_brackets:'Ortodoncia Brackets',
          ortodoncia_invisible:'Ortodoncia Invisible', endodoncia:'Endodoncia (Conducto)',
          corona_dental:'Corona Dental', limpieza_profunda:'Limpieza Profunda (Periodoncia)',
          blanqueamiento:'Blanqueamiento Dental', puente_dental:'Puente Dental',
        };
        const newProc = { key: parsed.newProcedureKey, name: allProcNames[parsed.newProcedureKey] || parsed.newProcedureKey };
        // Reset completo del estado SAGE para el nuevo procedimiento
        sage.procedure_key       = newProc.key;
        sage.procedure_name      = newProc.name;
        sage.specialty           = dentalKeys.includes(newProc.key) ? 'dental' : 'plastic_surgery';
        sage.state               = 'procedure_confirmed';  // motor cargará KB en el próximo msg
        sage.collected_data      = {};                     // limpiar datos del procedimiento anterior
        sage.current_q_index     = 1;
        sage.completeness_score  = 0;
        sage.intake_id           = null;
        sage.critical_questions  = null;                   // forzar reload de KB
        sage.required_info       = null;
        sage.required_exams      = null;
        finalOut.newSageContext   = sage;
        finalOut.shouldSaveIntake = false;                 // no guardar intake incompleto anterior
        finalOut.intakePayload    = null;

      } else if (parsed.escapeIntent === 'abort') {
        sage.state              = 'welcome';
        sage.collected_data     = {};
        sage.current_q_index    = 1;
        sage.completeness_score = 0;
        finalOut.newSageContext   = sage;
        finalOut.shouldSaveIntake = false;
        finalOut.intakePayload    = null;
      }
    }

    if (parsed.responseText && parsed.responseText.length > 5) {
      finalOut.responseText = parsed.responseText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── STATE: summary ──────────────────────────────────────────
  // ── STATE: procedure_confirmed (translation) ────────────────
  } else if (nlgState === 'procedure_confirmed') {
    if (rawText && rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }  
  } else if (nlgState === 'summary') {
    if (rawText.length > 20) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }

  // ── STATE: handoff_received / selecting_specialty ───────────
  } else if (nlgState === 'handoff_received' || nlgState === 'selecting_specialty') {
    const clean = rawText.replace(/```json\n?|```\n?/g, '').trim();
    try {
      const parsed = JSON.parse(clean);
      if (parsed.detectedProcedureKey && parsed.detectedSpecialty) {
        const sage = { ...(finalOut.newSageContext || {}) };
        const allProcNames = {
          rinoplastia:'Rinoplastia', abdominoplastia:'Abdominoplastia',
          liposuccion:'Liposucción', aumento_mamario:'Aumento de Busto',
          reduccion_mamaria:'Reducción de Busto', bichectomia:'Bichectomía',
          blefaroplastia:'Blefaroplastia (Párpados)', otoplastia:'Otoplastia (Orejas)',
          lifting_facial:'Lifting Facial', bbl:'BBL (Brazilian Butt Lift)',
          extraccion_simple:'Extracción Simple',
          extraccion_muela_juicio:'Extracción Muela del Juicio',
          implante_dental:'Implante Dental', protesis_completa:'Prótesis Dental Completa',
          carillas_veneers:'Carillas / Veneers', ortodoncia_brackets:'Ortodoncia Brackets',
          ortodoncia_invisible:'Ortodoncia Invisible', endodoncia:'Endodoncia (Conducto)',
          corona_dental:'Corona Dental', limpieza_profunda:'Limpieza Profunda (Periodoncia)',
          blanqueamiento:'Blanqueamiento Dental', puente_dental:'Puente Dental',
        };
        sage.specialty      = parsed.detectedSpecialty;
        sage.procedure_key  = parsed.detectedProcedureKey;
        sage.procedure_name = allProcNames[parsed.detectedProcedureKey] || parsed.detectedProcedureKey;
        sage.state          = 'procedure_confirmed';
        finalOut.newSageContext = sage;
      }
      if (parsed.responseText && parsed.responseText.length > 5) {
        finalOut.responseText = parsed.responseText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    } catch(e) {
      if (rawText.length > 10) {
        finalOut.responseText = rawText;
        finalOut._nlgSource   = 'claude_nlg';
      }
    }

  // ── Other states ────────────────────────────────────────────
  } else {
    if (rawText.length > 10) {
      finalOut.responseText = rawText;
      finalOut._nlgSource   = 'claude_nlg';
    }
  }

} catch(e) {
  finalOut._nlgError = e.message;
}

return [{ json: finalOut }];

// ============================================================
// 🔐 Strip PHI v1.0
// Elimina identificadores personales antes de llamar a Claude.
// PHI eliminado: userName, userPhone, claudeContext.userName
// Datos completos preservados en el payload principal para
// nodos downstream (WhatsApp, DB, Construir Respuesta Final).
// ============================================================
const inp = $input.first().json;

const phiClean = {
  ...inp,
  userName:  null,
  userPhone: null,
  ...(inp.claudeContext
    ? { claudeContext: { ...inp.claudeContext, userName: null } }
    : {})
};

// _phi_clean excluye también remoteJid e instance
const { remoteJid, instance, userPhone, ...clinicalOnly } = phiClean;

return [{ json: {
  ...inp,              // datos completos para nodos posteriores
  phi_stripped: true,
  _phi_clean: {
    ...clinicalOnly,   // solo datos clínicos para Claude
    userName:  null,
    userPhone: null
  }
}}];

const prepData    = $('📦 Preparar — NLG SAGE').first().json;
const claudeResp  = $input.first().json;

const sessionId    = prepData.sessionId || 'unknown';
const state        = prepData._nlgState || 'unknown';
const language     = prepData.detectedLanguage || prepData.userLanguage || 'es';
const model        = prepData.claudeSagePayload?.model || 'claude-sonnet-4-20250514';
const inputTokens  = claudeResp?.usage?.input_tokens  || 0;
const outputTokens = claudeResp?.usage?.output_tokens || 0;
const outputText   = claudeResp?.content?.[0]?.text   || '';

const PRICES = {
  'claude-sonnet-4-20250514':  { in: 3.00, out: 15.00 },
  'claude-haiku-4-5-20251001': { in: 0.80, out: 4.00  }
};
const p       = PRICES[model] || PRICES['claude-sonnet-4-20250514'];
const costUsd = ((inputTokens * p.in) + (outputTokens * p.out)) / 1_000_000;
const now     = new Date().toISOString();
const ts      = Date.now();

return [{ json: {
  _langfusePayload: {
    batch: [
      {
        id:        `trace-${sessionId}-${ts}`,
        type:      'trace-create',
        timestamp: now,
        body: {
          id:       `pangi-${sessionId}`,
          name:     `pangi-session-${sessionId}`,
          metadata: { session_id: sessionId, language, phi_stripped: prepData.phi_stripped || false }
        }
      },
      {
        id:        `sage-${sessionId}-${ts}`,
        type:      'generation-create',
        timestamp: now,
        body: {
          id:        `gen-sage-${sessionId}-${ts}`,
          traceId:   `pangi-${sessionId}`,
          name:      `sage-${state}`,
          model,
          startTime: now,
          endTime:   now,
          input:  { prompt: (prepData.claudeSagePayload?.system || '').substring(0, 800) },
          output: { text: outputText.substring(0, 500) },
          usage:  { input: inputTokens, output: outputTokens, unit: 'TOKENS' },
          metadata: {
            agent:        'SAGE',
            state,
            language,
            session_id:   sessionId,
            phi_stripped: prepData.phi_stripped || false,
            cost_usd:     parseFloat(costUsd.toFixed(6))
          }
        }
      }
    ]
  }
}}];
